def H(org_es="", org_ca=""):
    """Encabezado de escrito a una administración."""
    es = "En {t:ci}, a {fecha}.</p><p><b>A:</b> {n:b}.<br><b>De:</b> {n:a}, con DNI/NIE ____________, domicilio a efectos de notificaciones en {T:do}."
